/* Câu trả lời mẫu IELTS Speaking – đợt 2, cho more4.js (tự biên soạn) */
(function (g) { g.SPEAK_SAMPLES = Object.assign(g.SPEAK_SAMPLES || {}, {
/* ===== Nấu ăn tại nhà ===== */
"How often do you cook at home?": { a: "Pretty much every day, to be honest. I live with my sister, and we take it in turns to prepare dinner, so I'm in the kitchen four or five evenings a week. At weekends I like to experiment a bit more, maybe try a new recipe, whereas on busy weekdays I just throw together something quick and simple.", vocab: [["take it in turns", "luân phiên nhau"], ["throw together", "nấu vội, làm nhanh"], ["experiment with", "thử nghiệm với"]] },
"Who taught you to cook?": { a: "That would be my grandmother. I used to spend my summer holidays at her place in the countryside, and she let me help out in the kitchen from quite a young age. She never used measuring spoons, she just went by feel, so I learned to taste as I cooked rather than follow a recipe word for word.", vocab: [["help out", "phụ giúp"], ["go by feel", "làm theo cảm giác"], ["word for word", "từng chữ một"]] },
"Do you prefer eating at home or in restaurants?": { a: "I'd say I prefer eating at home, mainly because it's cheaper and I know exactly what goes into my food. That said, I do enjoy going out now and then, especially with friends, because it's a nice change of scene and somebody else does the washing up, which is a big plus for me.", vocab: [["a change of scene", "sự thay đổi không khí"], ["do the washing up", "rửa bát"], ["a big plus", "một điểm cộng lớn"]] },
"Is there a dish you would like to learn to make?": { a: "Yes, definitely, I've always wanted to master fresh pasta. I've watched loads of videos, and it looks simple, but I've heard the dough is really tricky to get right. I'd love to be able to make it from scratch for my family one day, rather than buying the packaged kind from the supermarket.", vocab: [["master", "thành thạo"], ["from scratch", "từ đầu, tự làm hoàn toàn"], ["get something right", "làm cho đúng"]] },
"Describe a meal you cooked for other people.": { a: "This is a story from last winter, when I decided to cook a proper dinner for my parents on their wedding anniversary. I wanted it to be a surprise, so I sent them to visit my aunt for the afternoon and quietly took over the kitchen. The menu was roast chicken with herbs, garlic potatoes and a crisp green salad, nothing fancy, but all things my mum loves. In terms of preparation, I marinated the chicken the night before, which was a clever move because the flavour went right through the meat. Mind you, there was a moment of panic when the timer went off and the potatoes were still pale, so I turned the oven up and crossed my fingers. Luckily, everything came together just as they walked through the door. At the table my dad went back for seconds, and my mum said it tasted like something from a proper restaurant, which honestly made my day. What I felt most was pride, mixed with relief, since cooking for people you love is more stressful than cooking for strangers. Afterwards, washing up with my dad, I realised how much effort they had put into feeding me for all those years, and that probably made the evening more emotional than I'd expected. I've since cooked for them twice more, though never with quite the same nerves.", vocab: [["take over the kitchen", "chiếm lấy bếp, lo bếp núc"], ["go back for seconds", "xin ăn thêm phần nữa"], ["make my day", "làm tôi vui cả ngày"]] },
"Why do fewer people cook from scratch nowadays?": { a: "I think time is the main factor. Many people work long hours and commute, so by the time they get home they're exhausted and it's far easier to heat up a ready meal or order a takeaway. On top of that, delivery apps have made food so convenient that cooking can feel like an unnecessary effort. Some people also simply never learned, because their parents were equally busy. So it becomes a kind of vicious circle, where convenience food replaces the skills that would let people cook for themselves.", vocab: [["ready meal", "bữa ăn làm sẵn"], ["on top of that", "thêm vào đó"], ["vicious circle", "vòng luẩn quẩn"]] },
"Should schools teach cooking as a compulsory subject?": { a: "I'm in favour of it, actually. Cooking is a basic life skill, yet many young adults leave home without knowing how to prepare a proper meal, and they end up relying on fast food. A compulsory class could also teach nutrition and food hygiene, which are useful for everybody. Having said that, I wouldn't want it to feel like a heavy burden on an already crowded timetable, so perhaps a short weekly session would be enough. Pupils might even enjoy it more than maths.", vocab: [["life skill", "kỹ năng sống"], ["rely on", "dựa vào"], ["crowded timetable", "thời khoá biểu dày đặc"]] },
"Does cooking at home really make people healthier?": { a: "Generally speaking, yes, although it isn't automatic. When you cook for yourself, you control the amount of salt, sugar and oil, whereas restaurants and packaged food tend to be loaded with all three. But I know people who cook at home every day and still eat badly, because they fry everything or make huge portions. So the habit helps, but what really matters is the ingredients you choose and your general knowledge about what a balanced diet looks like.", vocab: [["be loaded with", "chứa rất nhiều"], ["portion", "khẩu phần"], ["balanced diet", "chế độ ăn cân bằng"]] },
"How might food preparation change in the next few decades?": { a: "I suspect technology will play a much bigger role. We're already seeing smart ovens and appliances that follow a recipe automatically, and I can imagine that becoming standard in most homes. There may also be more personalised meals, designed around a person's health data or allergies. At the same time, I don't think traditional cooking will disappear, because many people find it relaxing and it's a way of connecting with family and culture. It might even become more of a hobby than a daily chore.", vocab: [["play a bigger role", "đóng vai trò lớn hơn"], ["personalised", "được cá nhân hoá"], ["daily chore", "việc vặt hằng ngày"]] },

/* ===== Âm nhạc trực tiếp ===== */
"Do you often listen to music while you are travelling?": { a: "Yes, almost always. I can't stand sitting on a bus or train in silence, so I put my headphones on as soon as I get in. I usually listen to calm playlists in the morning to wake me up gently, and something more upbeat on the way home. It makes the journey feel shorter, and it helps me block out the noise around me.", vocab: [["can't stand", "không chịu nổi"], ["upbeat", "sôi động, vui tươi"], ["block out", "chặn đi, lờ đi"]] },
"Have you ever been to a live concert?": { a: "Yes, a few times. The most recent one was a small indie band in a local theatre about six months ago. I'm not usually someone who goes to big stadium shows because the crowds put me off, but a smaller venue felt much more personal. You could actually see the musicians' faces, which made it far more enjoyable.", vocab: [["put someone off", "làm ai đó mất hứng"], ["venue", "địa điểm biểu diễn"], ["personal", "gần gũi, mang tính cá nhân"]] },
"What kind of music did you listen to when you were younger?": { a: "When I was a teenager I was really into pop-rock, mostly because that's what all my classmates were listening to. I used to copy lyrics into a notebook and sing along in my room. Looking back, some of those songs seem a bit cheesy now, but they still bring back good memories whenever I hear them by chance.", vocab: [["be into", "mê, thích"], ["sing along", "hát theo"], ["cheesy", "sến, hơi ngô nghê"]] },
"Would you like to learn to play a musical instrument?": { a: "Definitely, I've often thought about picking up the guitar. I tried the piano as a kid, but I gave up after a few months because I found the practice boring. Now that I'm older, I think I'd have more patience, and it would be a lovely way to unwind after a long day, as well as a skill I could share with friends.", vocab: [["pick up (an instrument)", "bắt đầu học (nhạc cụ)"], ["give up", "bỏ cuộc"], ["unwind", "thư giãn"]] },
"Describe a live music event you attended.": { a: "The first thing that comes to mind is an open-air concert I went to last summer, in a big park on the edge of my city. It was a one-day festival, and the main act was a singer-songwriter whose songs I'd been playing for years, so I'd been counting down the days. I went with two close friends, and we got there early to get a good spot near the stage. The atmosphere was just fantastic. The sun was going down, people were holding up their phone torches, and the whole crowd was singing along to the chorus of her biggest hit. I got a little emotional at that point, which was slightly embarrassing, although my friends were doing exactly the same thing. Who else performed? There were a couple of local bands earlier in the day, and one of them was surprisingly good, so I ended up following them online. Why do I remember it so well? I suppose it's because it felt so different from listening on headphones. You could feel the bass in your chest, and for a couple of hours everybody seemed connected. You simply can't recreate that at home, and whenever one of her songs comes on the radio now, I'm instantly back in that field. I'm already checking whether she's touring again, and I'd happily make the same trip.", vocab: [["main act", "nghệ sĩ chính"], ["get a good spot", "chiếm được chỗ tốt"], ["sing along to", "hát theo"]] },
"Why are live performances still popular in the age of streaming?": { a: "I think it's because a live show gives you something a recording simply can't, which is a shared experience. Streaming is convenient, but you're usually alone with your headphones, whereas at a concert you're surrounded by thousands of people who love the same music. There's also an element of unpredictability, since the musicians may improvise or change the arrangement. For many people, it's about creating memories rather than just listening, and that's why tickets still sell out so quickly.", vocab: [["shared experience", "trải nghiệm chung"], ["improvise", "ứng tác, ngẫu hứng"], ["sell out", "bán hết vé"]] },
"Should the government fund music festivals?": { a: "To some extent, yes. Festivals bring a lot of money into a region through tourism, hotels and local businesses, and they give young artists a chance to be heard. However, I don't think governments should pay for everything, particularly big commercial events that can easily make a profit on their own. A better approach might be to support smaller community festivals, which are important for local culture but often struggle financially. Public money should go where the cultural benefit is greatest.", vocab: [["to some extent", "ở một mức độ nào đó"], ["make a profit", "có lãi"], ["cultural benefit", "lợi ích văn hoá"]] },
"Does the music people like say something about their personality?": { a: "I think it can, but only to a limited degree. For example, people who enjoy calm instrumental music may tend to be more reflective, while fans of loud rock might be more energetic. But it's easy to fall into stereotypes. My own playlist includes everything from classical to hip-hop, depending on my mood. Music taste is often shaped by the friends and family around you, so it probably tells you more about someone's background than their character.", vocab: [["to a limited degree", "ở mức độ hạn chế"], ["reflective", "hay suy tư"], ["fall into stereotypes", "rơi vào định kiến"]] },
"How has technology changed the way musicians earn a living?": { a: "Quite dramatically. In the past, musicians relied on selling albums, but now most listeners stream, and the payment per play is tiny. As a result, many artists make their real money from touring and merchandise. On the positive side, technology has made it far easier to record at home and reach a global audience without a record label. So it's become tougher to earn a stable income, but easier for newcomers to get noticed in the first place.", vocab: [["rely on", "dựa vào"], ["merchandise", "hàng lưu niệm, đồ bán kèm"], ["stable income", "thu nhập ổn định"]] },

/* ===== Công viên & không gian xanh ===== */
"Is there a park near your home?": { a: "Yes, there's a fairly large one about ten minutes' walk from my flat. It has a lake in the middle, a running track and a children's playground, so it's always full of people at weekends. I'm really lucky to have it so close, because in a crowded city you don't often get that much open space within easy reach.", vocab: [["within easy reach", "trong tầm với, gần"], ["running track", "đường chạy bộ"], ["crowded city", "thành phố đông đúc"]] },
"What do you usually do when you visit a park?": { a: "Mostly I just walk around and clear my head. Sometimes I bring a book and find a bench under a tree, or I meet a friend and we have a coffee from the kiosk by the entrance. In spring I also like to take photos of the flowers, which is a nice way to slow down after a busy week.", vocab: [["clear my head", "làm đầu óc thoáng đãng"], ["slow down", "chậm lại, thư thả"], ["kiosk", "quầy bán hàng nhỏ"]] },
"Do you prefer spending time outdoors or indoors?": { a: "It really depends on the weather, but on the whole I prefer being outdoors. I spend most of the day inside at a desk, so I try to get fresh air whenever I can. That said, I'm quite happy to stay in on a cold, rainy evening with a film and a blanket. I suppose I like a bit of both.", vocab: [["on the whole", "nhìn chung"], ["get fresh air", "hít thở không khí trong lành"], ["stay in", "ở nhà"]] },
"Do you think your city has enough green space?": { a: "Not really, no. There are a few good parks, but they're mostly in the centre, and the newer districts have far fewer trees and open areas. As the population has grown, many empty plots have been turned into apartment blocks. I'd love to see more small gardens and tree-lined streets, because they make a real difference to how pleasant a neighbourhood feels.", vocab: [["open areas", "khu đất trống, thoáng"], ["empty plot", "mảnh đất trống"], ["tree-lined", "có hàng cây hai bên"]] },
"Describe a green space you like to spend time in.": { a: "My favourite green space has to be a botanical garden on the edge of my city, which I've been visiting since I was a student. It's half an hour away by bus and covers a huge area, with a pond, a rose garden and lots of shady paths. Early in the morning it's almost magical, because there's a thin mist over the water and you can hear birds everywhere, even though you're technically still in the city. Usually I start with a slow walk, then I settle beside the pond with a flask of tea and a notebook. Sometimes I try to sketch the plants, though I'm not very good at it, and my drawings look more like vegetables than flowers. I'll admit some of my best ideas have come to me there, probably because nothing is competing for my attention. If I'm stressed about work, I only need twenty minutes of wandering around before my head clears. So what makes it special? Mainly that it's the one place where I can properly switch off. It reminds me that a busy life doesn't have to be a stressful one, and every time I leave, I feel calmer than when I arrived. I'd go there daily if it were closer, and I keep telling my friends they should come along sometime.", vocab: [["shady", "có bóng mát"], ["switch off", "ngắt kết nối, thư giãn hẳn"], ["compete for attention", "tranh giành sự chú ý"]] },
"Why are green spaces important for people living in big cities?": { a: "There are several reasons. Firstly, they give people somewhere to exercise and relax, which is crucial for both physical and mental health, especially when many people live in small flats with no garden. Secondly, trees and plants help to clean the air and reduce the temperature during hot summers. Finally, parks act as meeting places where neighbours can interact, which strengthens the community. Without them, a city can feel cold, noisy and rather isolating.", vocab: [["mental health", "sức khoẻ tinh thần"], ["isolating", "gây cô lập"], ["strengthen the community", "gắn kết cộng đồng"]] },
"Should developers be allowed to build on parkland?": { a: "In general, I'd say no, or at least only in exceptional cases. Once you build on a park, it's practically impossible to get it back, and the long-term cost to residents is high. Developers often promise to create a smaller green area elsewhere, but that rarely replaces what has been lost. Of course, cities need housing, but there are usually other options, like regenerating abandoned industrial sites, which would cause far less harm.", vocab: [["exceptional cases", "trường hợp ngoại lệ"], ["regenerate", "tái phát triển, hồi sinh"], ["abandoned site", "khu đất bỏ hoang"]] },
"How can communities be encouraged to look after public spaces?": { a: "I think people look after places they feel a sense of ownership over. So local councils could involve residents in the planning, for instance by letting them vote on what to plant or build. Volunteer clean-up days and community gardens are also effective, because people who have put in effort tend to take care of the result. Fines for littering can help, but I believe positive incentives work better in the long term than punishment.", vocab: [["a sense of ownership", "cảm giác làm chủ, có phần trách nhiệm"], ["littering", "xả rác"], ["incentive", "sự khuyến khích"]] },
"Will cities of the future have more or less nature in them?": { a: "I'm cautiously optimistic that there'll be more. Many cities are already adding green roofs, vertical gardens and urban forests, mainly because of climate concerns. As land becomes more expensive, I imagine nature will be fitted into buildings rather than kept in large parks. However, there's a risk that it becomes a luxury only available in wealthy districts. So the key will be making sure that greenery is shared fairly across all neighbourhoods.", vocab: [["cautiously optimistic", "lạc quan một cách thận trọng"], ["green roof", "mái nhà xanh"], ["fitted into", "được lồng ghép vào"]] },

/* ===== Bảo tàng ===== */
"Do you enjoy going to museums?": { a: "Yes, I do, although I wouldn't say I'm a museum fanatic. I like visiting one when I'm travelling, because it's a quick way to understand a place. At home I tend to go only when there's a special exhibition that interests me. I find that a couple of hours is the ideal length, otherwise my brain starts to switch off.", vocab: [["fanatic", "người cuồng nhiệt"], ["special exhibition", "triển lãm đặc biệt"], ["switch off", "mất tập trung"]] },
"Did you visit museums on school trips?": { a: "Yes, quite often, actually. Our teachers organised a school trip about once a term, and the science museum was the one we all loved, since we could press buttons and try out the experiments. To be honest, I remember the snacks on the coach more than the history museum, which felt a bit dull when we had to fill in worksheets.", vocab: [["school trip", "chuyến đi dã ngoại của trường"], ["try out", "thử nghiệm"], ["dull", "tẻ nhạt"]] },
"What kind of exhibition would you most like to see?": { a: "I'd love to see something about ancient civilisations, ideally with real objects like jewellery, tools and pottery. There's something quite powerful about seeing things that people used thousands of years ago. I'm also interested in interactive exhibitions that recreate daily life, because they help you picture what it would have actually felt like to live in that period.", vocab: [["ancient civilisation", "nền văn minh cổ đại"], ["pottery", "đồ gốm"], ["recreate", "tái hiện"]] },
"Do you take photos when you visit museums?": { a: "Sometimes, when it's allowed. I tend to photograph the information panels as well as the objects, so I can read about them later. But I try not to overdo it, because I've noticed that if I'm busy taking pictures, I don't really look at the pieces properly. These days I take a few shots and then put my phone away.", vocab: [["information panel", "bảng thông tin"], ["overdo it", "làm quá mức"], ["put away", "cất đi"]] },
"Describe a museum or gallery you have visited.": { a: "Let me think, the museum that really stood out for me was a maritime museum that I visited with my cousin during a trip to a port city two summers ago. It was housed in an old warehouse right by the harbour, which gave it plenty of character before you even stepped inside. Inside, there were large models of ships, old maps, navigation instruments and even a full-size fishing boat that you were allowed to climb aboard. We stayed about three hours, and the guide, a retired sailor, told stories you'd never find on the information panels. What I loved was how hands-on everything was. You could steer a virtual ship through a storm, which turned out to be surprisingly difficult, and I managed to sink mine within a minute, much to my cousin's amusement. Something I didn't enjoy so much was that a few rooms were extremely crowded, so it was hard to read the displays properly, and the cafe was rather overpriced. Still, those are minor complaints. It was a thoroughly enjoyable visit, and I came away knowing far more about the sea than I ever expected. I'd happily recommend it to anyone who's interested in history, particularly if you can go on a weekday, when it's much quieter and you can talk to the staff. I'd gladly go back and see the sections we missed.", vocab: [["housed in", "được đặt trong"], ["hands-on", "thực hành, tương tác trực tiếp"], ["come away knowing", "ra về với hiểu biết"]] },
"Should entrance to museums be free for everyone?": { a: "I think there's a strong case for it, particularly for national museums. If entrance is free, people from all income levels can learn about their culture, and families are more likely to visit regularly rather than once a year. Some countries that have done this report a big rise in visitor numbers. The difficulty is funding, because museums still need money to look after their collections. A possible compromise would be free general entry, with charges for special exhibitions.", vocab: [["a strong case for", "lý lẽ mạnh mẽ ủng hộ"], ["income level", "mức thu nhập"], ["compromise", "giải pháp dung hoà"]] },
"Why do some young people find museums boring?": { a: "Probably because traditional museums can feel rather passive. You walk around, look at objects behind glass and read long labels, which doesn't compete with the instant, interactive entertainment that young people are used to on their phones. Also, if a school visit is linked to homework, it starts to feel like a chore. Museums that use games, touch screens and storytelling seem to attract teenagers much more successfully, because they feel involved rather than lectured.", vocab: [["passive", "thụ động"], ["compete with", "cạnh tranh với"], ["chore", "việc nhàm chán phải làm"]] },
"Is it right for museums to keep objects taken from other countries?": { a: "This is a really debated issue. On the one hand, large museums argue that they protect these objects and allow millions of visitors to see them. On the other hand, many of them were taken during colonial periods, often without proper consent, so there's a strong moral argument for returning them. Personally, I think each case should be judged individually. Where an object holds deep cultural significance, I believe it should go back, perhaps with loans arranged for display abroad.", vocab: [["colonial", "thuộc thời thuộc địa"], ["consent", "sự đồng ý"], ["cultural significance", "ý nghĩa văn hoá"]] },
"How could technology make museums more engaging?": { a: "There's a lot of potential. Augmented reality could let visitors point their phone at a skeleton and see the dinosaur come to life, for instance. Audio guides can be personalised so that a child gets a different story from an expert. Virtual tours also allow people who can't travel to explore the collections online. The only caution is that technology shouldn't take over, because the real objects are what make museums special in the first place.", vocab: [["augmented reality", "thực tế tăng cường"], ["come to life", "trở nên sống động"], ["take over", "lấn át"]] },

/* ===== Nghề thủ công ===== */
"Do you like making things with your hands?": { a: "Yes, I do, although I'm more of an amateur than an expert. I enjoy simple projects like repairing a chair or making a card for a friend's birthday. There's a real sense of satisfaction in finishing something yourself, and it gives my eyes a break from the screen, which is something I badly need.", vocab: [["amateur", "người nghiệp dư"], ["a sense of satisfaction", "cảm giác thoả mãn"], ["a break from", "sự nghỉ ngơi khỏi"]] },
"Have you ever bought something handmade?": { a: "Yes, I bought a ceramic mug from a stall at a weekend market a few months ago. The potter was sitting right there, shaping new pieces, so I could see how it was made. It cost twice as much as a shop mug, but I use it every morning and it makes my coffee feel a bit more special.", vocab: [["ceramic", "bằng gốm sứ"], ["stall", "quầy hàng"], ["potter", "thợ gốm"]] },
"Are traditional crafts popular in your country?": { a: "They used to be everywhere, but they're less common among young people now. In some villages, whole communities still make things like silk, bamboo baskets and pottery, and tourists love buying them. The government has also tried to promote them through craft festivals. I think there's a growing appreciation, though, because people are tired of mass-produced items that all look the same.", vocab: [["mass-produced", "sản xuất hàng loạt"], ["promote", "quảng bá"], ["appreciation", "sự trân trọng"]] },
"Would you like to learn a new craft?": { a: "I'd love to try woodworking. My uncle has a small workshop, and every time I visit I'm amazed at what he can make from a plain piece of timber. I imagine it takes a lot of patience, but I like the idea of building something useful, like a bookshelf, and being able to say I made it myself.", vocab: [["woodworking", "nghề mộc"], ["timber", "gỗ xẻ"], ["workshop", "xưởng nhỏ"]] },
"Describe something handmade that you own or have made.": { a: "I own quite a few handmade things, but the one that matters most is a woollen scarf that my aunt knitted for me when I started university. She lives in a small town up north and has been knitting since she was a girl. She knew I was moving to a much colder city, so she made it in a deep green, which is my favourite colour. According to her, it took about three weeks, working in the evenings in front of the television, and she used wool from a local farm. If you look closely, there are a few uneven stitches near one end, which I actually find rather charming, because it proves it didn't come from a factory. Why is it so important to me? Well, for a start, it's practical, since I wear it all winter and it's warmer than anything I could buy in the shops. But beyond that, it reminds me of her and of home, especially on those grey days when I feel a bit homesick. Whenever I wrap it round my neck, I can almost hear her telling me to look after myself. I've had it for six years now, and I wash it very carefully by hand. I'm already thinking about how to hand it down to my own children one day.", vocab: [["knit", "đan (len)"], ["stitch", "mũi đan, mũi khâu"], ["homesick", "nhớ nhà"]] },
"Why are handmade products usually more expensive than factory ones?": { a: "It comes down to time and skill. A craftsperson might spend hours or even days on a single item, whereas a machine can produce thousands in the same period. The materials are often higher quality, too, and small producers don't benefit from the cost savings of buying in bulk. In a way, you're paying for the person's expertise as well as the product. Many customers feel that's fair, because each piece is unique and tends to last longer.", vocab: [["it comes down to", "suy cho cùng là do"], ["in bulk", "với số lượng lớn"], ["expertise", "chuyên môn"]] },
"Is it important to pass traditional skills on to young people?": { a: "I think it is, because these skills carry a lot of cultural identity. If they disappear, we lose not only techniques but also stories and values connected to them. Besides, some traditional skills, like repairing things, are becoming relevant again as people think more about waste. The challenge is making them attractive to young people, who may see them as old-fashioned. Apprenticeships, school workshops and online videos could all help to keep these skills alive.", vocab: [["cultural identity", "bản sắc văn hoá"], ["apprenticeship", "học việc"], ["old-fashioned", "lỗi thời"]] },
"Can craft businesses compete with mass production?": { a: "Not on price, but they can on other things. Craft businesses offer uniqueness, quality and a story, and that appeals to customers who are fed up with identical products. Online platforms have also helped enormously, since a small maker can now sell directly to customers abroad. The difficulty is staying profitable without losing the personal touch, so the most successful ones tend to focus on a narrow, premium market rather than trying to match factory output.", vocab: [["fed up with", "chán ngấy"], ["profitable", "có lãi"], ["the personal touch", "nét riêng, dấu ấn cá nhân"]] },
"Do you think hobbies like crafting improve people's wellbeing?": { a: "Absolutely. Working with your hands requires concentration, which gives your mind a rest from worries, a bit like meditation. You also get a tangible result at the end, which boosts your confidence. Some hospitals even use art and craft sessions to help patients recover. I would add that doing it in a group, such as a knitting circle, brings a social benefit too, because loneliness is a real issue for many people these days.", vocab: [["tangible", "hữu hình, cụ thể"], ["boost confidence", "tăng sự tự tin"], ["loneliness", "sự cô đơn"]] },

/* ===== Thư viện ===== */
"Do you often go to the library?": { a: "Not as often as I'd like, to be honest. During exam periods I go nearly every day because it's quiet and I can concentrate there, but the rest of the year I might only go once a month. I do enjoy the atmosphere, though. Everyone is working silently, which weirdly makes me more productive.", vocab: [["exam period", "mùa thi"], ["concentrate", "tập trung"], ["productive", "làm việc hiệu quả"]] },
"Do you prefer borrowing books or buying them?": { a: "It depends on the book. If it's something I'll only read once, I borrow it, because it saves money and space. But if I really love a book, I like to own a copy so I can underline things and read it again. My shelves are already packed, so I've become a bit more selective about what I buy.", vocab: [["selective", "kén chọn"], ["underline", "gạch chân"], ["packed", "chật kín"]] },
"Where do you usually read?": { a: "Mostly in bed before sleeping, which is a habit I've had for years. At weekends I sometimes read in a cafe near my flat, as I like the background chatter and a cup of tea. I rarely read on the train because I get a bit travel-sick, so I listen to podcasts there instead.", vocab: [["background chatter", "tiếng ồn nền, tiếng chuyện trò"], ["travel-sick", "say xe"], ["a habit", "thói quen"]] },
"Did you read a lot as a child?": { a: "Yes, I was a real bookworm. My mum took me to the local library every Saturday, and I'd come home with a pile of adventure stories and comics. I used to read under the covers with a torch after lights out. I think that early habit helped my vocabulary a lot, and it's probably why I still enjoy reading now.", vocab: [["bookworm", "mọt sách"], ["under the covers", "dưới chăn"], ["lights out", "giờ tắt đèn đi ngủ"]] },
"Describe a library you have used.": { a: "Okay, so the library I know best is the central library in my home city, which I practically lived in while I was preparing for my final exams. It's a big, modern building near the river, with five floors, and each floor is dedicated to a different kind of material. Inside, it's very bright thanks to the huge glass windows, and the reading areas have comfortable chairs, so you can stay for hours without ending up with a sore back. On the top floor there's a small cafe with a view over the water, and that was my favourite spot for a short break. As for what I did there, I mostly studied, but I also borrowed novels and, from time to time, went to a free language exchange evening on Thursdays, where I practised English with people from all over the world. Would I recommend it? Absolutely. The staff are friendly, the wifi is dependable, and it's one of the few places in the city where you can get genuine peace and quiet. If I'm honest, I think it helped me pass my exams, because having a proper place to study kept me disciplined and stopped me from drifting off to my phone. I still pop in whenever I'm back in town, and the librarians even remember my face, which is rather sweet.", vocab: [["dedicated to", "dành riêng cho"], ["language exchange", "trao đổi ngôn ngữ"], ["peace and quiet", "sự yên tĩnh"]] },
"Do libraries still have a place in the digital age?": { a: "I believe they do, although their role is changing. Not everyone can afford books, a laptop or a stable internet connection, and libraries provide all of these for free. They're also quiet, welcoming spaces, which are becoming rare in busy cities. Sure, most information is online, but a librarian can help you find reliable sources, which is a valuable skill when there's so much misinformation. So I'd say they've adapted rather than become obsolete.", vocab: [["obsolete", "lỗi thời, không còn dùng"], ["misinformation", "thông tin sai lệch"], ["adapt", "thích nghi"]] },
"Should public libraries offer more than books?": { a: "Yes, I think they should, because that's how they stay relevant. Many libraries already offer computer access, children's story hours, job-hunting workshops and even board game nights. These services attract people who might never borrow a book but who still benefit from the space. The only risk is spreading the budget too thin, so libraries need to make sure the core service, access to books and information, isn't weakened by all the extras.", vocab: [["stay relevant", "luôn phù hợp"], ["job-hunting", "tìm việc"], ["spread too thin", "dàn trải quá mỏng"]] },
"Why do some people prefer paper books to e-books?": { a: "There are a few reasons. Many readers love the physical experience, like the smell of the pages and the feel of turning them. Studies also suggest that people remember more of what they read on paper, perhaps because it's easier to navigate and there are no notifications to distract you. Then there's the simple pleasure of a bookshelf, which says something about who you are. For me, a screen feels too much like work, so paper helps me relax.", vocab: [["navigate", "định hướng, lật tìm"], ["distract", "làm xao nhãng"], ["notification", "thông báo (điện thoại)"]] },
"Who should pay for public libraries, the state or local people?": { a: "I think it should mainly be the state, through taxation, since libraries benefit the whole society by raising literacy and supporting education. If they relied only on local funding, libraries in poorer areas would suffer, which would widen the gap between communities. That said, I see nothing wrong with local people contributing through donations or volunteering, because it builds a sense of ownership. A combination, with the state covering the basics, seems the fairest approach.", vocab: [["taxation", "thuế khoá"], ["literacy", "khả năng biết đọc viết"], ["widen the gap", "nới rộng khoảng cách"]] },

/* ===== Thời tiết & mùa ===== */
"What is the weather usually like where you live?": { a: "It's quite humid for most of the year. Summers are hot and sticky, with sudden heavy showers in the afternoon, while winters are mild but a bit grey and damp. We don't really get snow, so a dry, sunny day is something people appreciate. I think I've got used to it, although I can't say I enjoy the humidity.", vocab: [["humid", "ẩm ướt"], ["heavy shower", "mưa rào lớn"], ["get used to", "quen với"]] },
"Which season do you like best?": { a: "Autumn, without a doubt. The temperature is comfortable, so you don't have to hide from the heat or wrap up in layers, and the light has a lovely golden quality. It's also when many local festivals take place. I find it the perfect time to be outdoors, whether I'm walking or just having coffee on a terrace.", vocab: [["wrap up", "mặc ấm"], ["in layers", "mặc nhiều lớp"], ["golden light", "ánh sáng vàng dịu"]] },
"Does the weather affect your mood?": { a: "It does, more than I'd like to admit. When it's grey and drizzly for days, I feel sluggish and less motivated, whereas sunshine puts me in a much better mood. I've learned to deal with it by getting outside during my lunch break, even if it's just for a short walk, because natural light seems to help.", vocab: [["drizzly", "mưa phùn"], ["sluggish", "uể oải"], ["motivated", "có động lực"]] },
"What do you do on rainy days?": { a: "I usually stay in and do something cosy. I might cook a big pot of soup, watch a series or catch up on reading. If I have to go out, I carry a compact umbrella everywhere. Actually, I sometimes find the sound of rain on the window quite relaxing, so I don't mind it as much as some people do.", vocab: [["cosy", "ấm cúng"], ["catch up on", "bù lại, làm nốt"], ["compact", "nhỏ gọn"]] },
"Describe a time when bad weather changed your plans.": { a: "Funny you should ask, because this happened only last spring. A few colleagues and I had planned a hiking trip, a day out in the mountains that we'd been looking forward to for weeks. The idea was to set off at dawn and walk to a waterfall about ten kilometres from the car park. Unfortunately, a storm moved in much earlier than forecast, and we woke up to thick cloud and heavy rain. The paths were slippery, and there were even flood warnings on the local radio. At first we were really disappointed, and two of the group wanted to go anyway, but we agreed that it wasn't worth the risk. So what did we do instead? We drove to a small town nearby, found a cosy cafe and spent the whole afternoon playing cards, drinking hot chocolate and eating far too much cake. Strangely enough, it turned out to be one of the most enjoyable days we'd ever had together, because we talked much more than we would have on a trail. Some people even said it was better than the hike would have been. It taught me that a change of plan can sometimes turn into a pleasant surprise, and now I always keep a rainy-day option in mind, usually a cafe or a cinema, just in case the forecast lets us down again.", vocab: [["move in", "kéo đến (cơn bão)"], ["not worth the risk", "không đáng để mạo hiểm"], ["a change of plan", "thay đổi kế hoạch"]] },
"Why do people in different countries talk about the weather so much?": { a: "I think it's a safe, neutral topic that helps you strike up a conversation. Everybody experiences the weather, so it's an easy way to start a conversation with a stranger without being too personal. In countries where the weather changes quickly, like the UK, it also happens to be genuinely useful to know what to expect. And culturally, it's become a kind of ritual, a polite opening before you move on to more serious subjects, and almost everyone knows how to play along.", vocab: [["neutral topic", "chủ đề trung lập"], ["ritual", "nghi thức, thói quen mang tính tục lệ"], ["strike up a conversation", "bắt chuyện"]] },
"How does extreme weather affect daily life and the economy?": { a: "The impact can be enormous. Floods and storms damage homes and roads, which stops people getting to work and disrupts supply chains. Farmers lose crops during droughts, and then food prices go up for everyone. In addition, businesses have to spend more on insurance and repairs. The poorest households suffer most, because they have fewer savings to recover with. As extreme events become more frequent, this cost is likely to keep rising.", vocab: [["disrupt", "làm gián đoạn"], ["supply chain", "chuỗi cung ứng"], ["drought", "hạn hán"]] },
"Should people be forced to leave areas that are often hit by storms or floods?": { a: "Forcing people is a very sensitive matter, so I'd avoid it wherever possible. People have deep ties to their homes, and moving them can destroy communities. A better approach might be to offer generous financial support and new housing for those who choose to relocate, while investing in flood defences for the rest. However, if an area is truly too dangerous, then in the long run the government may have little choice, because repeatedly rescuing people costs lives and money.", vocab: [["ties to", "gắn bó với"], ["relocate", "di dời"], ["flood defences", "công trình chống lũ"]] },
"Will weather forecasts become more reliable in the future?": { a: "I'm fairly sure they will become more reliable. Satellites, sensors and computing power are improving all the time, and artificial intelligence can spot patterns in huge amounts of data. Short-term forecasts are already far better than they were twenty years ago. However, the atmosphere is a chaotic system, so long-range predictions will probably always carry some uncertainty. What will matter is communicating that uncertainty clearly, so that people take warnings seriously and prepare in time.", vocab: [["reliable", "đáng tin cậy"], ["chaotic system", "hệ thống hỗn loạn"], ["uncertainty", "sự bất định"]] },

/* ===== Thư từ & tin nhắn ===== */
"Do you prefer sending messages or calling people?": { a: "I'm definitely a messaging person. It's less intrusive, because the other person can reply when it suits them, and I can think about what I want to say. That said, if something is complicated or emotional, I'd rather call, since it's easy for the tone of a text to be misunderstood. So I use both, depending on the situation.", vocab: [["intrusive", "xâm phạm, làm phiền"], ["suit someone", "phù hợp với ai"], ["tone", "giọng điệu"]] },
"Have you ever written a letter by hand?": { a: "Yes, but only a handful of times. I wrote one to a pen friend in another country when I was about twelve, and recently I wrote a thank-you letter to a teacher. It felt strangely slow, but also much more personal. Your handwriting says something about you, and I think the recipient appreciated the effort.", vocab: [["a handful of", "một vài"], ["pen friend", "bạn qua thư"], ["recipient", "người nhận"]] },
"How quickly do you usually reply to messages?": { a: "It varies. If it's from my family or a close friend, I'll answer within a few minutes. For work or less urgent chats, I might leave it until I have a free moment, and sometimes I forget altogether, which has got me into trouble more than once. I'm trying to be better, but I don't like feeling pressured to respond immediately.", vocab: [["urgent", "khẩn cấp"], ["get into trouble", "gặp rắc rối"], ["feel pressured", "cảm thấy bị áp lực"]] },
"Do you keep any old messages or cards?": { a: "Yes, I have a shoebox full of birthday cards and notes from friends, some of which go back to primary school. I don't look at them often, but I can't bring myself to throw them away. I also keep a few screenshots of messages that made me laugh or feel proud, which is a modern version of the same habit, I suppose.", vocab: [["can't bring myself to", "không nỡ lòng nào"], ["go back to", "có từ thời"], ["screenshot", "ảnh chụp màn hình"]] },
"Describe a message or letter that meant a lot to you.": { a: "There's one message that I've never deleted, and it's from my best friend, sent the evening I failed my driving test for the first time. It wasn't a long letter or anything formal, just a text, but it arrived at exactly the right moment. I was feeling pretty low and embarrassed, because I'd told everyone I would definitely pass. What did it say? Something along the lines of: failing a test doesn't change who you are, and you'll be a better driver because of what you've learned. She also added a funny photo of herself trying to park, which made me laugh out loud on the bus. I must have read it five times on the way home. Why did it mean so much to me? I think it's because she didn't try to cheer me up with empty phrases. She was honest, a bit humorous, and it was obvious she'd thought about what to write. It made me feel supported rather than judged, which is rarer than you might think. I passed on my second attempt, a month later, and she was the first person I told. Even now, that message is saved in my phone, so if I ever feel discouraged I can pull it up and remember that somebody believes in me. I tell her about it sometimes, and she just laughs and says she doesn't even remember writing it.", vocab: [["feel low", "cảm thấy chán nản"], ["cheer someone up", "làm ai đó vui lên"], ["empty phrases", "những lời sáo rỗng"]] },
"Has instant messaging made communication better or worse?": { a: "I'd say it's a bit of both. It's certainly made things faster and cheaper, so families who live in different countries can stay in touch every day. But the quality of conversation can suffer, because messages tend to be short and fragmented, and it's easy to misread the tone. There's also the pressure to be constantly available, which can be exhausting. So the technology is brilliant, but how we use it matters a great deal.", vocab: [["stay in touch", "giữ liên lạc"], ["fragmented", "rời rạc"], ["constantly available", "lúc nào cũng phải sẵn sàng trả lời"]] },
"Why do some people still prefer formal letters?": { a: "Mainly because a letter carries more weight. For things like job applications, legal matters or an official complaint, a printed letter looks serious and can serve as evidence. Some people also feel an email is too casual for important occasions, such as a condolence note or a wedding invitation. And for older generations, there's often simple habit and a certain distrust of digital systems. So a letter is still seen as a mark of respect.", vocab: [["carry weight", "có trọng lượng, có sức nặng"], ["condolence", "lời chia buồn"], ["a mark of respect", "biểu hiện của sự tôn trọng"]] },
"Are young people losing the ability to write properly?": { a: "I don't think it's quite that simple. Young people write all the time, but in a casual style with abbreviations and emojis, and that can carry over into school work. So some may struggle to switch to a formal register. On the other hand, they're used to expressing ideas quickly and creatively. I think the key is for schools to teach different styles for different situations, rather than blaming technology for everything.", vocab: [["abbreviation", "từ viết tắt"], ["register", "văn phong, mức độ trang trọng"], ["carry over", "lan sang, mang sang"]] },
"How might communication between people change in the future?": { a: "I expect it to become more immersive. Video calls could be replaced by virtual reality meetings where people feel as if they're in the same room, and real-time translation might remove language barriers altogether. That would be wonderful for global friendships and business. However, I worry that face-to-face conversation could become less common, and that would be a real loss, since a lot of human connection relies on small details like body language and shared silence.", vocab: [["immersive", "nhập vai, đắm chìm"], ["language barrier", "rào cản ngôn ngữ"], ["body language", "ngôn ngữ cơ thể"]] },

/* ===== Thể thao mạo hiểm ===== */
"Do you enjoy doing anything risky?": { a: "I'd say I enjoy calculated risks rather than reckless ones. I like trying things that feel slightly out of my comfort zone, like speaking in front of a large group or travelling to a country where I don't speak the language. But I'm not the sort of person who would do something dangerous just for the thrill, because I always think about the consequences.", vocab: [["calculated risk", "rủi ro được tính toán"], ["comfort zone", "vùng an toàn"], ["reckless", "liều lĩnh"]] },
"Have you ever tried an unusual sport?": { a: "Yes, I once tried rock climbing on an indoor wall with some friends. It was much harder than it looks, and my arms were aching for days afterwards. But I loved the problem-solving aspect, because you have to plan every move. I've been back a couple of times since, and I'm slowly getting better.", vocab: [["ache", "đau nhức"], ["problem-solving", "giải quyết vấn đề"], ["get better", "tiến bộ dần"]] },
"Would you like to go skydiving or bungee jumping?": { a: "Honestly, no, not really. I'm quite afraid of heights, and the idea of jumping out of a plane makes my palms sweat. I can see the appeal, though, and I've got friends who say it was the best day of their lives. Maybe if I were braver, I'd give it a go, but at the moment I'll stay on the ground.", vocab: [["afraid of heights", "sợ độ cao"], ["see the appeal", "hiểu được sức hấp dẫn"], ["give it a go", "thử xem sao"]] },
"Do you prefer watching sports or taking part?": { a: "I definitely prefer taking part. Watching a match on television can be exciting, but I get restless after a while, and I'd rather be moving. When I play, I feel more energetic and I sleep better. I do enjoy watching big tournaments with friends, though, as the atmosphere makes it a social occasion rather than just a game.", vocab: [["restless", "bồn chồn"], ["take part", "tham gia"], ["social occasion", "dịp giao lưu"]] },
"Describe an exciting outdoor activity you have tried or would like to try.": { a: "Right, so what I'd choose is white-water rafting, which I tried last summer and would happily do again. You paddle an inflatable boat down a fast river as a team, and a guide steers from the back. I did it in a mountain region a few hours from my city, with five friends from university, and we'd booked months in advance because it gets very busy in summer. I was quite nervous at the start, especially when the instructor explained what to do if we fell in. But within ten minutes of paddling, the nerves had turned into pure excitement. At one rapid the boat nearly flipped over, and we were all screaming and laughing at the same time. After the run, we sat on the riverbank eating sandwiches that tasted better than anything I'd had for months. What appeals to me about it is the mix of teamwork and adrenaline. You can't do it alone, so you really get to know the people you're with. On top of that, you're surrounded by gorgeous scenery, which makes it feel like a proper adventure rather than just exercise. I'm already planning to try a harder river next year, assuming my friends are brave enough to join me again. Honestly, I think the whole group is hooked now, and nobody wants to go back to ordinary weekends.", vocab: [["white-water rafting", "chèo thuyền vượt thác"], ["adrenaline", "adrenaline, cảm giác phấn khích"], ["flip over", "lật úp"]] },
"Why are some people attracted to dangerous sports?": { a: "I think there are a few motivations. Some people want the adrenaline rush, because it makes them feel intensely alive, particularly if their daily routine is predictable. Others are driven by the challenge of pushing their limits and proving something to themselves. And for some, it's a way of escaping stress, because when you're climbing a cliff, you can't think about emails. In fact, many extreme sports athletes say they feel calm, not scared, as they've trained thoroughly.", vocab: [["adrenaline rush", "cơn phấn khích adrenaline"], ["push one's limits", "thử thách giới hạn bản thân"], ["trained thoroughly", "luyện tập kỹ càng"]] },
"Should the cost of rescuing adventurers be paid by the adventurers themselves?": { a: "It's a tricky question. If someone is rescued after ignoring clear warnings or taking unnecessary risks, I think it's reasonable to ask them to contribute, because rescue operations are expensive and use public resources. On the other hand, if people knew they would get a huge bill, they might not call for help until it's too late, which could cost lives. So I'd support a mandatory insurance system instead, where adventurers cover the risk in advance.", vocab: [["rescue operation", "chiến dịch cứu hộ"], ["mandatory", "bắt buộc"], ["in advance", "từ trước"]] },
"Do extreme sports teach valuable life skills?": { a: "I believe they can. Activities like climbing or kayaking teach you to stay calm under pressure, to assess risks properly and to trust your teammates. Those are useful skills at work and in relationships, too. Having said that, the same benefits can come from less dangerous activities, such as team sports or hiking, so you don't necessarily need to risk your neck to build character. It depends on the person and how well the activity is supervised.", vocab: [["under pressure", "dưới áp lực"], ["assess risks", "đánh giá rủi ro"], ["risk one's neck", "liều mạng"]] },
"How can adventure tourism be made safer and more sustainable?": { a: "On safety, I'd say the key is strict regulation, with licensed guides, regular equipment checks and clear briefings before every activity. For sustainability, operators should limit group sizes, so that fragile landscapes are not worn down, and employ local people so that the profit stays in the community. Tourists have a part to play, too, by choosing responsible companies even if they are slightly more expensive. Done well, adventure tourism can actually fund the protection of nature.", vocab: [["strict regulation", "quy định nghiêm ngặt"], ["fragile", "mong manh, dễ tổn hại"], ["briefing", "buổi hướng dẫn trước khi làm"]] },

/* ===== Mua sắm đồ cũ ===== */
"Have you ever bought something second-hand?": { a: "Yes, quite a lot, actually. Most of my furniture is second-hand, including my desk and a bookshelf, which I found through an online marketplace. I also buy clothes from charity shops now and then. It's cheaper, and you often find better quality than modern, cheaply made items, so I've never been disappointed.", vocab: [["charity shop", "cửa hàng từ thiện"], ["marketplace", "chợ (trực tuyến)"], ["cheaply made", "làm rẻ tiền, kém chất lượng"]] },
"Do you like going to markets?": { a: "I do, especially flea markets on weekends. I enjoy the lively atmosphere and the chance to bargain, which I find quite fun. You never know what you might stumble across, whether it's a vintage camera or a nice old lamp. I don't always buy anything, but I like to wander around and chat to the stallholders.", vocab: [["flea market", "chợ đồ cũ"], ["bargain", "mặc cả"], ["stumble across", "tình cờ tìm thấy"]] },
"What do you do with things you no longer need?": { a: "I try not to throw things away if they're still usable. Clothes and books usually go to a charity shop, and if something is in good condition, I'll sell it online or give it to a friend. Anything broken I take to a recycling point. It takes a bit more effort, but I hate the idea of waste.", vocab: [["in good condition", "trong tình trạng tốt"], ["usable", "còn dùng được"], ["recycling point", "điểm thu gom tái chế"]] },
"Do you prefer shopping online or in shops?": { a: "It depends on what I'm buying. For basic things like cables or toiletries, online is quicker and often cheaper. But for clothes or shoes, I prefer going to a shop, because I can try them on and avoid the hassle of returns. I also find browsing in real shops more relaxing, as long as it isn't too crowded.", vocab: [["try on", "mặc thử"], ["the hassle of", "sự phiền hà của"], ["browse", "dạo xem"]] },
"Describe something you bought second-hand.": { a: "One of my best buys ever was a vintage film camera that I picked up about two years ago. I found it at a weekend flea market in my city, on a stall full of old electronics and tools. It was a compact seventies model with a leather case, sitting at the back of the table looking rather dusty. The seller, an older man, told me he'd taken it on his honeymoon, which I thought was lovely. After a bit of friendly bargaining, I paid the equivalent of about twenty pounds, which felt like a fair deal. Was I happy with it? Very much so. At first I wasn't sure it still worked, so I bought a roll of film and went out to test it. The first set of photos was a bit blurry, to be honest, but after a few attempts I got the hang of it, and now I love the soft, warm colours it produces. My friends think I'm slightly mad for waiting a week to see my pictures, but I enjoy the suspense. What I like most is that it has a history. It makes me slow down and think about every shot, instead of snapping hundreds of pictures on my phone. All things considered, it was money well spent, and I've since bought a second lens from the same stall. The seller still waves whenever I walk past.", vocab: [["vintage", "cổ điển, đồ xưa"], ["a fair deal", "một thương vụ công bằng"], ["get the hang of", "nắm được cách làm"]] },
"Why is second-hand shopping becoming more popular?": { a: "I think there are three main drivers. First, money: with the cost of living rising, people are looking for bargains. Second, environmental awareness, because buying used items means fewer new things are produced. And third, technology, since apps and websites have made it very simple to buy and sell, which removes the hassle of visiting dozens of shops. It has also become more fashionable, with influencers showing off their vintage finds, so the old stigma is fading.", vocab: [["cost of living", "chi phí sinh hoạt"], ["stigma", "sự kỳ thị, tiếng xấu"], ["driver", "động lực, nhân tố thúc đẩy"]] },
"Does buying used goods really help the environment?": { a: "In most cases, yes, because making new products takes raw materials, energy and water, and extending the life of an existing item avoids all of that. Clothes are a good example, as the fashion industry produces a huge amount of pollution. However, the benefit shrinks if people buy more simply because the items are cheap, or if goods are shipped long distances. So it helps, but only if it replaces new purchases rather than adding to them.", vocab: [["raw materials", "nguyên liệu thô"], ["extend the life of", "kéo dài tuổi thọ của"], ["shipped", "được vận chuyển"]] },
"Why do some people feel embarrassed about owning used items?": { a: "Often it's about status. Some people see new products as a sign of success, so using something second-hand feels like admitting they can't afford better. There's also a hygiene worry, particularly with clothes or mattresses. And social media doesn't help, as it puts pressure on us to show off the latest things. Younger people seem to care less, though, which suggests that attitudes are gradually shifting towards valuing practicality over appearances.", vocab: [["status", "địa vị xã hội"], ["show off", "khoe khoang"], ["practicality", "tính thực tế"]] },
"Should companies be made to produce longer-lasting products?": { a: "I believe so, at least for certain categories like electronics and appliances. At the moment, many products are designed to break after a few years, or they're so hard to repair that it makes more sense to replace them. Rules requiring a minimum lifespan, spare parts and repair manuals would cut waste and save consumers money. Companies might complain about lower sales, but they could earn more through repair services and by building a reputation for quality.", vocab: [["appliance", "thiết bị gia dụng"], ["lifespan", "tuổi thọ"], ["spare parts", "phụ tùng thay thế"]] }
}); })(typeof self !== 'undefined' ? self : this);
